def is_valid_polyomino(grid, h, w):
    visited = [[False] * w for _ in range(h)]
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def dfs(x, y, start_x, start_y):
        if x < 0 or x >= h or y < 0 or y >= w or grid[x][y] == '.' or visited[x][y]:
            return True
        visited[x][y] = True
        for dx, dy in directions:
            if not dfs(x + dx, y + dy, start_x, start_y):
                return False
        return True

    for i in range(h):
        for j in range(w):
            if grid[i][j] == 'X' and not visited[i][j]:
                if not dfs(i, j, i, j):
                    return False
    return True

def find_polyomino_power(h, w, grid):
